#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

require_command() {
  if ! command -v "$1" >/dev/null 2>&1; then
    printf 'missing required command: %s\n' "$1" >&2
    exit 1
  fi
}

supabase_cli() {
  npx --yes supabase@2.121.0 "$@"
}

base64_text() {
  node -e 'process.stdout.write(Buffer.from(process.argv[1], "utf8").toString("base64"))' "$1"
}

sql_text() {
  printf "decode('%s', 'base64')::text" "$(base64_text "$1")"
}

run_sql_file() {
  local sql="$1"
  local tmp="$TEMP_SQL_FILE"

  if ! printf '%s\n' "$sql" > "$tmp"; then
    rm -f "$tmp"
    return 1
  fi

  if ! supabase_cli db query --file "$tmp" --project-ref "$PROJECT_REF"; then
    rm -f "$tmp"
    return 1
  fi

  rm -f "$tmp"
}

run_wizard() {
  local script_dir repo_root
  script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
  repo_root=$(cd -- "$script_dir/.." && pwd)
  cd "$repo_root"

  PROJECT_REF="zgmyabmxxtgzbeplodde"
  ENV_FILE="$repo_root/supabase/functions/.env"
  TEMP_SQL_FILE="$repo_root/supabase/.temp/notification-wizard.sql"
  mkdir -p "$(dirname -- "$ENV_FILE")"
  mkdir -p "$(dirname -- "$TEMP_SQL_FILE")"
  trap 'rm -f -- "$TEMP_SQL_FILE"' EXIT

  TOTAL_STAGES=12

  banner "RepairHub Email notification production setup"

  stage "前置：scoped Supabase token 與資料庫連線"
  say "此流程會設定 Resend、Supabase secrets/Vault、部署 migration 與 Edge Function，最後做真實寄信 E2E。"
  require_command npx
  require_command node
  require_command git
  note "舊版線上 Edge Function 曾內嵌 Resend key；完成新版本 E2E 後必須撤銷舊 key。"
  open_url "https://supabase.com/dashboard/account/tokens"
  step "建立一個只限 RepairHub 專案的 scoped access token。"
  step "權限至少包含：Project Settings Read、API Keys Read、API Key Secrets Read、Database Read-write、Migrations Read-write、Edge Functions Read-write、Edge Function Secrets Read-write、Advisors Read。"
  if [[ -z "${SUPABASE_ACCESS_TOKEN:-}" ]]; then
    ask_secret SUPABASE_ACCESS_TOKEN "Paste the scoped Supabase access token:"
  fi
  if [[ "$SUPABASE_ACCESS_TOKEN" != sbp_fc* ]]; then
    warn "token 不是 scoped 格式（通常以 sbp_fc 開頭）。"
    if ! confirm "仍要使用這個 token？"; then
      exit 1
    fi
    SKIPPED+=("確認 Supabase access token 只限 RepairHub 專案與必要權限")
  fi
  export SUPABASE_ACCESS_TOKEN

  if [[ -z "${SUPABASE_DB_PASSWORD:-}" ]]; then
    ask_secret SUPABASE_DB_PASSWORD "資料庫密碼（若 CLI 會提示才需要，否則直接 Enter）："
  fi
  if [[ -n "${SUPABASE_DB_PASSWORD:-}" ]]; then
    export SUPABASE_DB_PASSWORD
  else
    note "未提供資料庫密碼；若 Supabase CLI 要求，會由 CLI 自行提示。"
  fi

  if ! git check-ignore -q "$ENV_FILE"; then
    printf 'refusing to continue: %s is not gitignored\n' "$ENV_FILE" >&2
    exit 1
  fi

  supabase_cli link --project-ref "$PROJECT_REF"

  stage "Resend：驗證 notify.monyu.dev"
  say "寄件網域必須先驗證，否則 Edge Function 會收到 Resend 的 403。"
  open_url "https://resend.com/domains"
  step "Add Domain，輸入 notify.monyu.dev。"
  step "依照 Resend 顯示的 SPF、DKIM 記錄，到 monyu.dev 的 DNS 供應商新增記錄。"
  step "等待 Resend Dashboard 顯示 Verified；DNS 傳播可能需要數分鐘到數小時。"
  open_url "https://resend.com/docs/dashboard/domains/dmarc"
  step "依 Resend 文件設定 DMARC；monyu.dev 目前採較嚴格的郵件政策。"
  if ! confirm "Resend 已顯示 notify.monyu.dev 為 Verified？"; then
    warn "請先完成網域驗證再繼續，否則後續 E2E 會失敗。"
    SKIPPED+=("確認 notify.monyu.dev 的 SPF、DKIM 與 DMARC")
  fi

  stage "Resend：建立受限的 production API key"
  open_url "https://resend.com/api-keys"
  step "Create API Key，名稱使用 repairhub-production。"
  step "Permission 選 Sending access，並限制只能使用 notify.monyu.dev。"
  ask_secret RESEND_API_KEY "Paste the Resend sending API key:"
  if [[ "$RESEND_API_KEY" != re_* ]]; then
    warn "Resend API key 通常以 re_ 開頭；請確認複製的是 API key，而不是 webhook signing secret。"
  fi
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  note "舊 key 先保留到 E2E 成功；成功後再撤銷任何曾出現在舊 Edge Function 的 key。"

  stage "Supabase Edge Function secrets"
  write_env RESEND_FROM "RepairHub <no-reply@notify.monyu.dev>"
  write_env APP_BASE_URL "https://repairhub.monyu.dev"
  ask RESEND_REPLY_TO "Paste the monitored Reply-To mailbox:"
  write_env RESEND_REPLY_TO "$RESEND_REPLY_TO"

  local existing_secret
  existing_secret=$(_existing REPAIRHUB_EDGE_FUNCTION_SECRET || true)
  if [[ -n "$existing_secret" ]]; then
    REPAIRHUB_EDGE_FUNCTION_SECRET="$existing_secret"
  else
    REPAIRHUB_EDGE_FUNCTION_SECRET=$(node -e 'console.log(require("crypto").randomBytes(32).toString("hex"))')
  fi
  write_env REPAIRHUB_EDGE_FUNCTION_SECRET "$REPAIRHUB_EDGE_FUNCTION_SECRET"
  chmod 600 "$ENV_FILE" 2>/dev/null || true

  step "推送 Edge Function secrets 到 Supabase；secret 只從 gitignored 的本機檔案讀取。"
  supabase_cli secrets set --env-file "$ENV_FILE" --project-ref "$PROJECT_REF"
  supabase_cli secrets list --project-ref "$PROJECT_REF"
  if ! confirm "上方 secret 名稱包含 RESEND_API_KEY、RESEND_FROM、RESEND_REPLY_TO、APP_BASE_URL、REPAIRHUB_EDGE_FUNCTION_SECRET？"; then
    warn "secret 名稱不完整，後續部署會失敗。"
    SKIPPED+=("確認 Supabase Edge Function secrets 清單")
  fi
  note "目前四種通知不使用 Resend delivery webhook；重播去重會在 ledger claim 邊界驗證，因此不建立沒有 consumer 的 webhook secret。"

  stage "Supabase Vault：DB 呼叫 Edge Function"
  say "Vault 只保存資料庫呼叫 Edge Function 所需的 URL 與內部 secret。"
  if ! confirm "寫入或更新 repairhub_project_url 與 repairhub_edge_function_secret？"; then
    printf 'Vault secrets are required before migrations can invoke the Edge Function.\n' >&2
    exit 1
  fi

  local project_url url_b64 secret_b64 vault_sql
  project_url="https://${PROJECT_REF}.supabase.co"
  url_b64=$(base64_text "$project_url")
  secret_b64=$(base64_text "$REPAIRHUB_EDGE_FUNCTION_SECRET")
  vault_sql=$(cat <<SQL
DO \$\$
DECLARE
  secret_id UUID;
BEGIN
  SELECT id INTO secret_id
  FROM vault.secrets
  WHERE name = 'repairhub_project_url'
  LIMIT 1;

  IF secret_id IS NULL THEN
    PERFORM vault.create_secret(
      decode('${url_b64}', 'base64')::text,
      'repairhub_project_url',
      'RepairHub notification Edge Function URL'
    );
  ELSE
    PERFORM vault.update_secret(
      secret_id,
      decode('${url_b64}', 'base64')::text,
      'repairhub_project_url',
      'RepairHub notification Edge Function URL'
    );
  END IF;

  SELECT id INTO secret_id
  FROM vault.secrets
  WHERE name = 'repairhub_edge_function_secret'
  LIMIT 1;

  IF secret_id IS NULL THEN
    PERFORM vault.create_secret(
      decode('${secret_b64}', 'base64')::text,
      'repairhub_edge_function_secret',
      'RepairHub internal Edge Function secret'
    );
  ELSE
    PERFORM vault.update_secret(
      secret_id,
      decode('${secret_b64}', 'base64')::text,
      'repairhub_edge_function_secret',
      'RepairHub internal Edge Function secret'
    );
  END IF;
END
\$\$;
SQL
)
  run_sql_file "$vault_sql"
  supabase_cli db query "select count(*) = 2 as vault_secrets_ready from vault.secrets where name in ('repairhub_project_url', 'repairhub_edge_function_secret');" --project-ref "$PROJECT_REF"
  if ! confirm "vault_secrets_ready 為 true？"; then
    warn "Vault 尚未就緒。"
    SKIPPED+=("確認 Supabase Vault secrets")
  fi

  stage "部署 Edge Function"
  step "先部署新版 Edge Function，再套用 retry migration。"
  supabase_cli functions deploy send-ticket-email --project-ref "$PROJECT_REF" --no-verify-jwt --use-api
  supabase_cli functions list --project-ref "$PROJECT_REF"
  if ! confirm "send-ticket-email 顯示 ACTIVE？"; then
    warn "Edge Function 尚未成功部署。"
    SKIPPED+=("確認 send-ticket-email 部署狀態")
  fi

  stage "收斂 pg_net schema"
  say "既有 production 的 pg_net 安裝在 public；Supabase 文件說明它不可搬移，必須先確認 queue 為空再重建到 extensions。"
  supabase_cli db query "select n.nspname as pg_net_schema from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname = 'pg_net';" --project-ref "$PROJECT_REF"
  if supabase_cli db query "select count(*) as pending_pg_net_requests from net.http_request_queue;" --project-ref "$PROJECT_REF"; then
    note "若 pending_pg_net_requests 不是 0，請等 queue 清空後再繼續；drop/recreate 會丟棄 queue 與已保存的 response。"
  else
    note "pg_net 尚未安裝；migration 會在 extensions 建立。"
  fi

  if confirm "上方有顯示 pg_net_schema，且值是 public？"; then
    if ! confirm "已確認 pending_pg_net_requests 為 0，且可以重建 pg_net？"; then
      printf 'pg_net relocation is required before applying the notification migrations.\n' >&2
      exit 1
    fi
    supabase_cli db query "create schema if not exists extensions; drop extension if exists pg_net; drop schema if exists net; create extension pg_net with schema extensions;" --project-ref "$PROJECT_REF"
  fi

  stage "套用 migration 與 retry cron"
  step "先 dry-run 確認只會套用通知相關 migration。"
  supabase_cli db push --project-ref "$PROJECT_REF" --dry-run
  if ! confirm "確認套用上方 migration？"; then
    exit 1
  fi
  supabase_cli db push --project-ref "$PROJECT_REF"
  supabase_cli db query "select to_regclass('public.notification_log') is not null as notification_log_ready, to_regprocedure('public.process_due_notification_deliveries()') is not null as retry_function_ready, to_regprocedure('public.enqueue_new_ticket_notification()') is not null as new_ticket_ready, exists (select 1 from cron.job where jobname = 'repairhub-notification-delivery-retry') as retry_cron_ready, (select n.nspname = 'extensions' from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname = 'pg_net') as pg_net_in_extensions;" --project-ref "$PROJECT_REF"
  if ! confirm "五個值皆為 true？"; then
    warn "migration 或 cron 尚未完整部署。"
    SKIPPED+=("確認 notification migration 與 retry cron")
  fi

  stage "E2E：四種通知"
  say "使用真實可收信地址建立測試 Ticket，不要用 Resend owner-only test address。"
  open_url "https://repairhub.monyu.dev"
  step "確認測試 Category 有 active、已訂閱且 Email 正確的 Technician。"
  step "建立一筆帶照片的測試 Ticket，Reporter 使用可收信測試信箱。"
  step "確認 Technician 收到「新報修案件」Email。"
  step "將 Ticket 移到 in_progress，確認 Reporter 收到「已開始維修」Email。"
  step "將 Ticket 移到 completed，確認 Reporter 收到「已完工，請確認」與七天提醒。"
  step "將 Ticket 移到 closed，確認 Reporter 收到「已結案」Email。"
  ask E2E_TICKET_ID "Paste the test Ticket UUID:"
  ask E2E_REPORTER_EMAIL "Paste the Reporter test Email:"
  ask E2E_TECHNICIAN_EMAIL "Paste one Technician Email that received new_ticket:"

  local ticket_expr reporter_expr technician_expr e2e_sql
  ticket_expr=$(sql_text "$E2E_TICKET_ID")
  reporter_expr=$(sql_text "$E2E_REPORTER_EMAIL")
  technician_expr=$(sql_text "$E2E_TECHNICIAN_EMAIL")
  e2e_sql=$(cat <<SQL
select
  bool_or(event_type = 'new_ticket' and lower(recipient_email) = lower(${technician_expr}) and status = 'sent' and resend_message_id is not null) as new_ticket_sent,
  bool_or(event_type = 'in_progress' and lower(recipient_email) = lower(${reporter_expr}) and status = 'sent' and resend_message_id is not null) as in_progress_sent,
  bool_or(event_type = 'completed' and lower(recipient_email) = lower(${reporter_expr}) and status = 'sent' and resend_message_id is not null) as completed_sent,
  bool_or(event_type = 'closed' and lower(recipient_email) = lower(${reporter_expr}) and status = 'sent' and resend_message_id is not null) as closed_sent,
  count(*) filter (where status = 'failed') as failed_deliveries
from public.notification_log
where ticket_id = ${ticket_expr};
SQL
)
  run_sql_file "$e2e_sql"
  if ! confirm "四個 sent 值皆為 true、failed_deliveries 為 0，且四個信箱都已收到？"; then
    warn "四種通知尚未完成 E2E。"
    SKIPPED+=("完成四種通知的真實寄信 E2E")
  fi

  stage "E2E：重播不重複寄送"
  say "對已寄送的 delivery 再呼叫一次；sent 狀態會被 claim 拒絕，不應產生新 Email。"
  local replay_sql
  replay_sql=$(cat <<SQL
with candidate as (
  select id
  from public.notification_log
  where ticket_id = ${ticket_expr}
    and status = 'sent'
  order by created_at
  limit 1
)
select public.invoke_notification_delivery(id) is null as replay_suppressed
from candidate;
SQL
)
  run_sql_file "$replay_sql"
  if ! confirm "replay_suppressed 為 true，且收件匣沒有新增重複 Email？"; then
    warn "重播去重尚未通過。"
    SKIPPED+=("驗證重播不重複寄送")
  fi

  stage "E2E：暫時性失敗的持久重試"
  say "這一步會插入一筆模擬 failed delivery、立即觸發既有 retry 路徑，並真的寄出一封測試 Email。"
  if ! confirm "建立這筆測試 delivery 並寄出？"; then
    SKIPPED+=("驗證暫時性失敗的持久重試")
  else
    local retry_sql
    retry_sql=$(cat <<SQL
DO \$\$
DECLARE
  inserted_id UUID;
BEGIN
  INSERT INTO public.notification_log (
    ticket_id,
    event_type,
    event_key,
    recipient_email,
    status,
    attempt_count,
    next_attempt_at,
    last_error
  )
  VALUES (
    ${ticket_expr},
    'in_progress',
    'e2e-retry:' || gen_random_uuid()::text,
    ${reporter_expr},
    'failed',
    1,
    now(),
    'E2E simulated transient failure'
  )
  RETURNING id INTO inserted_id;

  PERFORM public.invoke_notification_delivery(inserted_id);
END
\$\$;
SQL
)
    run_sql_file "$retry_sql"
    sleep 30
    supabase_cli db query "select status = 'sent' and resend_message_id is not null as retry_succeeded, status = 'failed' and attempt_count >= 5 and next_attempt_at is null as retry_permanently_failed, attempt_count, last_error from public.notification_log where event_key like 'e2e-retry:%' order by created_at desc limit 1;" --project-ref "$PROJECT_REF"
    if ! confirm "retry_succeeded 為 true，或 retry_permanently_failed 為 true？"; then
      warn "尚未觀察到正確的 retry 終態；可稍後重跑查詢或檢查 Edge Function logs。"
      SKIPPED+=("確認暫時性失敗的最終重試或 failed state")
    fi
  fi

  stage "安全檢查與 secret hygiene"
  supabase_cli db advisors --project-ref "$PROJECT_REF" --type security --level warn --fail-on none
  step "確認本次 notification 功能沒有新增 security advisor finding；既有且無關的 finding 需另行處理。"
  supabase_cli db query "select not has_table_privilege('anon', 'public.notification_log', 'SELECT') as anon_cannot_read, not has_table_privilege('authenticated', 'public.notification_log', 'SELECT') as authenticated_cannot_read, n.nspname = 'extensions' as pg_net_in_extensions from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname = 'pg_net';" --project-ref "$PROJECT_REF"
  if ! confirm "anon_cannot_read、authenticated_cannot_read 與 pg_net_in_extensions 皆為 true？"; then
    warn "安全權限或 pg_net schema 尚未通過檢查。"
    SKIPPED+=("確認通知 ledger 權限與 pg_net schema")
  fi

  if git grep -nE 're_[A-Za-z0-9_-]{20,}|sbp_[A-Za-z0-9_-]{20,}' -- . ':!package-lock.json'; then
    warn "tracked files 疑似含 API key；請確認並移除。"
    SKIPPED+=("移除 tracked files 中疑似 secret")
  else
    note "tracked files 未發現明顯的 Resend/Supabase token 格式。"
  fi
  if [[ -f "$ENV_FILE" ]]; then
    note "本機 secret 檔：$ENV_FILE（已 gitignore；內容不會輸出）。"
  fi
  if ! confirm "已完成新版本 E2E，且已撤銷舊版 Edge Function 使用過的 Resend API key？"; then
    SKIPPED+=("撤銷舊版 Edge Function 使用過的 Resend API key")
  fi

  finish
}

run_wizard "$@"; exit
